<script lang="ts">import { onMount } from 'svelte'; import { page } from '$app/state'; import { api } from '$lib/api'; let lead=$state<any>(null),error=$state(''); onMount(async()=>{try{lead=await api(`/leads/${page.params.id}`)}catch(e){error=(e as Error).message}}); const stages=['Enquiry','Contacted','Counselling','Application','Admission'];</script>{#if error}<p class="text-red-300">{error}</p>{:else if lead}<div class="max-w-4xl space-y-6"><a href="/student-leads" class="text-sm text-accent">← Student Leads</a><div class="flex justify-between"><div><h1 class="text-3xl font-bold text-white">{lead.student_name}</h1><p class="text-text-secondary mt-2">Lead details and operational admission journey.</p></div><span class="h-fit px-3 py-2 rounded-full bg-accent/15 text-accent text-sm">{lead.lead_status}</span></div><div class="grid md:grid-cols-2 gap-5"><section class="card"><h2>Student Information</h2><p>Email: {lead.email??'Not provided'}</p><p>Location: {lead.location??'Not provided'}</p></section><section class="card"><h2>Academic Information</h2><p>{lead.qualification??'Not provided'}</p><p>Score: {lead.academic_score??'—'}</p></section><section class="card"><h2>Admission Interest</h2><p>Course: {lead.course_interested??'—'}</p><p>Program: {lead.program??'—'}</p></section><section class="card"><h2>AI Intelligence</h2><p class="text-text-secondary">No prediction has been generated yet.</p><div class="mt-4 flex gap-3"><a href="/admission-prediction" class="text-accent text-sm">View Prediction →</a><a href="/explainable-ai" class="text-accent text-sm">Explain Prediction →</a></div></section></div><section class="card"><h2>Lead Journey</h2><div class="flex flex-wrap gap-3 mt-4">{#each stages as stage}<span class:current={stage===lead.lead_status} class="stage">{stage}</span>{/each}</div></section></div>{:else}<p class="text-text-secondary">Loading lead…</p>{/if}<style>.card{background:var(--color-card);border:1px solid rgba(255,255,255,.1);padding:1.5rem;border-radius:1rem}.card h2{color:white;font-weight:bold;margin-bottom:.75rem}.card p{font-size:.875rem;color:#a7a4b4;margin:.35rem 0}.stage{padding:.5rem .75rem;border-radius:.6rem;background:rgba(255,255,255,.06);font-size:.8rem;color:#a7a4b4}.stage.current{background:rgba(164,123,224,.15);color:#a47be0;border:1px solid rgba(164,123,224,.3)}</style>
